const data = $('Calcular Duracion Loop').first().json;
const timestamp = data.timestamp;
const outputPath = `E:\\RainTube\\output\\${timestamp}_final.mp4`;
const fs = require('fs');

let fileSize = 'desconocido';
try {
  const stats = fs.statSync(outputPath);
  fileSize = (stats.size / (1024 * 1024 * 1024)).toFixed(2) + ' GB';
} catch(e) {}

return [{ json: {
  tema: data.tema,
  video_final: outputPath,
  duracion_horas: data.duracion_horas,
  tamano: fileSize,
  timestamp: timestamp,
  archivos_video: data.archivos_video,
  archivos_audio: data.archivos_audio
} }];
